// The Elder Gaunt's Pixel Lab animations (2026-11-19, ArtSource/mutants_anim/gaunt/pixellab/README.md; the table is ElderClips.Data.cs, generated by ArtSource/export_elder_clips.py).
// Each clip is a strip Sprites/Mutants/anim/elder_gaunt_<clip>.bytes of Cells cells (W x H), played in `Step` order with `Ms` per step (the roar repeats and shakes cells, the combos list the cell of every step).
// Combos (combo2/3/4) are also registered as attack animations so MutantAttack can play them: Contacts are the ms at which a hit lands, the last combo4 contact is the slam's ring.
using System.Collections.Generic;
using GameData;
using UnityEngine;

namespace GameCore
{
    public static partial class ElderClips
    {
        public class Clip { public int Cells; public int[] Step, Ms, Contacts; public int TotalMs; }
        public class ComboAnim : AttackAnim { public int[] Contacts; public bool SlamLast; }

        public static Clip Get(string name) => name != null && All.TryGetValue(name, out var c) ? c : null;
        /// <summary>The cell to show `tMs` after the clip began (the last step holds), or -1.</summary>
        public static int CellAt(Clip c, float tMs)
        {
            if (c == null) return -1; float acc = 0f;
            for (int i = 0; i < c.Ms.Length; i++) { acc += c.Ms[i]; if (tMs < acc) return c.Step[i]; }
            return c.Step[c.Step.Length - 1];
        }
        /// <summary>The picture of `clip` at `tMs`, or null when the strip is not in the project.</summary>
        public static Sprite Sprite(string clip, float tMs)
        {
            var c = Get(clip); if (c == null) return null;
            var frames = UnitSprites.GauntAnim(Gaunt.ElderName, clip, c.Cells); if (frames == null) return null;
            return frames[Mathf.Clamp(CellAt(c, tMs), 0, frames.Length - 1)];
        }
        public static bool Has(string clip) => Get(clip) != null && UnitSprites.GauntAnim(Gaunt.ElderName, clip, Get(clip).Cells) != null;
        public static float Seconds(string clip) => (Get(clip)?.TotalMs ?? 0) / 1000f;

        static bool _registered;
        /// <summary>Puts the combos into MutantAttackData (the strip files, sizes and hit times) the first time the attack table is read.</summary>
        public static void Register()
        {
            if (_registered) return; _registered = true;
            if (!MutantAttackData.Table.TryGetValue(Gaunt.ElderName, out var t)) MutantAttackData.Table[Gaunt.ElderName] = t = new Dictionary<string, AttackAnim>();
            foreach (var kv in All)
            {
                if (!kv.Key.StartsWith("combo")) continue; var c = kv.Value;
                int ci = 0, acc = 0; while (ci < c.Ms.Length && acc < c.Contacts[0]) acc += c.Ms[ci++];
                t[kv.Key] = new ComboAnim { Frames = c.Cells, W = W, H = H, Contact = ci, ContactMs = c.Contacts[0], TotalMs = c.TotalMs, PivotY = PivotY, Ms = c.Ms, Travel = new float[c.Ms.Length], Contacts = c.Contacts, SlamLast = kv.Key == "combo4" };
            }
        }
    }
}
